import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.BTjPRYTP.js";const k=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),n={name:"guide/getting-started.md"};function l(r,t,h,o,p,d){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide walks you through setting up TeslaSync from scratch. By the end, you&#39;ll have a fully running instance tracking your Tesla fleet.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before you begin, make sure you have the following installed on your machine:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Minimum Version</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="https://docs.docker.com/get-docker/" target="_blank" rel="noreferrer">Docker</a></td><td>24.0+</td><td>Container runtime</td></tr><tr><td><a href="https://docs.docker.com/compose/install/" target="_blank" rel="noreferrer">Docker Compose</a></td><td>2.20+</td><td>Multi-service orchestration</td></tr><tr><td><a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a></td><td>2.30+</td><td>Clone the repository</td></tr></tbody></table><p>For local development without Docker, you&#39;ll also need:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Minimum Version</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="https://go.dev/dl/" target="_blank" rel="noreferrer">Go</a></td><td>1.22+</td><td>Backend compilation</td></tr><tr><td><a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js</a></td><td>20 LTS</td><td>Frontend build tooling</td></tr><tr><td><a href="https://www.postgresql.org/" target="_blank" rel="noreferrer">PostgreSQL</a></td><td>17+</td><td>Database</td></tr></tbody></table><h3 id="tesla-developer-account" tabindex="-1">Tesla Developer Account <a class="header-anchor" href="#tesla-developer-account" aria-label="Permalink to &quot;Tesla Developer Account&quot;">​</a></h3><p>You <strong>must</strong> register a Tesla developer application to obtain API credentials:</p><ol><li>Go to <a href="https://developer.tesla.com/" target="_blank" rel="noreferrer">developer.tesla.com</a> and sign in with your Tesla account.</li><li>Create a new application.</li><li>Note down your <strong>Client ID</strong> and <strong>Client Secret</strong>.</li><li>Set the <strong>Redirect URI</strong> to <code>http://localhost:8080/api/v1/auth/callback</code> (or your production URL).</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Tesla API access requires an active Tesla account with at least one vehicle linked. The Fleet API is rate-limited — TeslaSync includes a circuit breaker to handle this gracefully.</p></div><h2 id="clone-the-repository" tabindex="-1">Clone the Repository <a class="header-anchor" href="#clone-the-repository" aria-label="Permalink to &quot;Clone the Repository&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/ev-dev-labs/TeslaSync.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TeslaSync</span></span></code></pre></div><h2 id="configure-environment-variables" tabindex="-1">Configure Environment Variables <a class="header-anchor" href="#configure-environment-variables" aria-label="Permalink to &quot;Configure Environment Variables&quot;">​</a></h2><p>Copy the example environment file and fill in your Tesla API credentials:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Open <code>.env</code> in your editor and set the required values:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Tesla API (REQUIRED)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TESLA_CLIENT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-client-id-here</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TESLA_CLIENT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-client-secret-here</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TESLA_REDIRECT_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:8080/api/v1/auth/callback</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Database (defaults work for Docker Compose)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POSTGRES_USER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">teslasync</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POSTGRES_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">teslasync</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POSTGRES_DB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">teslasync</span></span></code></pre></div><p>See the <a href="/teslasync/guide/configuration.html">Configuration</a> page for all available options.</p><h2 id="start-with-docker-compose" tabindex="-1">Start with Docker Compose <a class="header-anchor" href="#start-with-docker-compose" aria-label="Permalink to &quot;Start with Docker Compose&quot;">​</a></h2><p>The fastest way to get TeslaSync running is with Docker Compose, which starts all 6 services:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>This will start:</p><table tabindex="0"><thead><tr><th>Service</th><th>Port</th><th>Description</th></tr></thead><tbody><tr><td><strong>web</strong></td><td><a href="http://localhost:3000" target="_blank" rel="noreferrer">localhost:3000</a></td><td>React frontend (Nginx)</td></tr><tr><td><strong>teslasync</strong></td><td><a href="http://localhost:8080" target="_blank" rel="noreferrer">localhost:8080</a></td><td>Go API server</td></tr><tr><td><strong>postgres</strong></td><td>localhost:5432</td><td>PostgreSQL database</td></tr><tr><td><strong>grafana</strong></td><td><a href="http://localhost:3001" target="_blank" rel="noreferrer">localhost:3001</a></td><td>Monitoring dashboards</td></tr><tr><td><strong>mosquitto</strong></td><td>localhost:1883</td><td>MQTT broker</td></tr><tr><td><strong>redis</strong></td><td>localhost:6379</td><td>Cache layer</td></tr></tbody></table><h3 id="verify-services-are-running" tabindex="-1">Verify Services Are Running <a class="header-anchor" href="#verify-services-are-running" aria-label="Permalink to &quot;Verify Services Are Running&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check all containers are healthy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check backend health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/healthz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check readiness (DB + Tesla API)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/readyz</span></span></code></pre></div><h2 id="authenticate-with-tesla" tabindex="-1">Authenticate with Tesla <a class="header-anchor" href="#authenticate-with-tesla" aria-label="Permalink to &quot;Authenticate with Tesla&quot;">​</a></h2><p>Once the services are running, you need to link your Tesla account:</p><ol><li>Open the TeslaSync web UI at <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>.</li><li>Navigate to <strong>Settings</strong> or click the login prompt.</li><li>You&#39;ll be redirected to Tesla&#39;s OAuth2 login page.</li><li>Sign in with your Tesla account and authorize TeslaSync.</li><li>After authorization, you&#39;ll be redirected back to TeslaSync.</li></ol><p>Alternatively, use the API directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Get the Tesla OAuth login URL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/v1/auth/login</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check authentication status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/v1/auth/status</span></span></code></pre></div><h2 id="sync-your-vehicles" tabindex="-1">Sync Your Vehicles <a class="header-anchor" href="#sync-your-vehicles" aria-label="Permalink to &quot;Sync Your Vehicles&quot;">​</a></h2><p>After authentication, sync your fleet:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Via API</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/v1/vehicles/sync</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or use the web UI&#39;s &quot;Sync Vehicles&quot; button on the Vehicles page</span></span></code></pre></div><p>TeslaSync will begin polling your vehicles at the configured interval (default: every 15 seconds) and storing telemetry data.</p><h2 id="explore-the-dashboard" tabindex="-1">Explore the Dashboard <a class="header-anchor" href="#explore-the-dashboard" aria-label="Permalink to &quot;Explore the Dashboard&quot;">​</a></h2><p>Open <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a> to access the full web interface:</p><ul><li><strong>Dashboard</strong> — Fleet overview with live stats</li><li><strong>Live Map</strong> — Real-time GPS tracking</li><li><strong>Vehicles</strong> — Vehicle details and current state</li><li><strong>Drives</strong> — Historical drive data</li><li><strong>Charging</strong> — Charging session history and costs</li><li><strong>Analytics</strong> — Fleet-wide metrics and charts</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/teslasync/guide/configuration.html">Configuration</a> — Tune polling intervals, data retention, and more</li><li><a href="/teslasync/guide/local-development.html">Local Development</a> — Set up the dev environment</li><li><a href="/teslasync/guide/architecture.html">Architecture</a> — Understand how TeslaSync works under the hood</li><li><a href="/teslasync/deployment/docker.html">Docker Deployment</a> — Production Docker setup</li></ul>`,40)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
